package com.moviebox.tv;
import org.junit.Test;
import org.json.JSONObject;
import static org.junit.Assert.*;
public class WatchHistoryTest {
 static class Memory implements WatchHistory.Storage {String value="[]";boolean fail=false;public String read(){return value;}public boolean write(String s){if(fail)return false;value=s;return true;}}
 static JSONObject request(int episode) throws Exception {return new JSONObject("{\"item\":{\"id\":{\"provider\":\"moviebox\",\"value\":\"base\"},\"title\":\"A story\",\"poster_url\":null},\"context\":{\"provider\":\"moviebox\",\"id\":\"hindi\",\"season\":1,\"episode\":"+episode+"},\"audio_language\":\"hin\",\"release\":{\"resource_id\":\"r1\",\"filename\":\"Cut\",\"url\":\"https://private.invalid/token\",\"headers\":[[\"Cookie\",\"secret\"]]},\"resume_seconds\":84}");}
 @Test public void persistsPlayerReportedPositionAndContext() throws Exception {Memory m=new Memory();WatchHistory h=new WatchHistory(m);h.begin(request(2));h.record(864123,3600000,false);JSONObject row=new WatchHistory(m).list().getJSONObject(0);assertEquals(864.123,row.getDouble("position"),.001);assertEquals(2,row.getJSONObject("context").getInt("episode"));assertEquals("hindi",row.getJSONObject("context").getString("id"));assertEquals("hin",row.getString("audio_language"));assertFalse(m.value.contains("private.invalid"));assertFalse(m.value.contains("secret"));}
 @Test public void episodesSeparateAndLatestFirst() throws Exception {WatchHistory h=new WatchHistory(new Memory());h.begin(request(1));h.record(20000,100000,false);h.begin(request(2));h.record(30000,100000,false);assertEquals(2,h.list().length());assertEquals(2,h.list().getJSONObject(0).getJSONObject("context").getInt("episode"));}
 @Test public void startOverReplacesPosition() throws Exception {WatchHistory h=new WatchHistory(new Memory());h.begin(request(1));h.record(80000,100000,false);h.end();h.begin(request(1).put("resume_seconds",0));h.record(1000,100000,false);assertEquals(1,h.list().length());assertEquals(1,h.list().getJSONObject(0).getDouble("position"),0);}
 @Test public void completionAt95Percent() throws Exception {WatchHistory h=new WatchHistory(new Memory());h.begin(request(1));h.record(94999,100000,false);assertFalse(h.list().getJSONObject(0).getBoolean("completed"));h.record(95000,100000,false);assertTrue(h.list().getJSONObject(0).getBoolean("completed"));}
 @Test public void endedWithoutKnownDuration() throws Exception {WatchHistory h=new WatchHistory(new Memory());h.begin(request(1));h.record(45000,0,true);assertTrue(h.list().getJSONObject(0).getBoolean("completed"));}
 @Test public void removeStopsActiveResurrection() throws Exception {WatchHistory h=new WatchHistory(new Memory());h.begin(request(1));h.record(20000,100000,false);String key=h.list().getJSONObject(0).getString("key");h.remove(key);h.record(30000,100000,false);assertEquals(0,h.list().length());}
 @Test public void clearNeedsConfirmationAndStopsResurrection() throws Exception {WatchHistory h=new WatchHistory(new Memory());h.begin(request(1));h.record(20000,100000,false);try{h.clear(false);fail();}catch(IllegalArgumentException expected){}assertEquals(1,h.list().length());h.clear(true);h.record(30000,100000,false);assertEquals(0,h.list().length());}
 @Test public void unknownDurationAndNegativePosition() throws Exception {WatchHistory h=new WatchHistory(new Memory());h.begin(request(1));h.record(-1,-1,false);assertEquals(0,h.list().length());h.record(42000,-1,false);assertFalse(h.list().getJSONObject(0).getBoolean("completed"));assertEquals(0,h.list().getJSONObject(0).getInt("duration"));}
 @Test public void failedWriteKeepsCommittedItems() throws Exception {Memory m=new Memory();WatchHistory h=new WatchHistory(m);h.begin(request(1));h.record(42000,100000,false);m.fail=true;try{h.clear(true);fail();}catch(IllegalStateException expected){}assertEquals(1,h.list().length());}
 @Test public void corruptStorageNotSilentlyOverwritten() throws Exception {Memory m=new Memory();m.value="invalid";try{new WatchHistory(m);fail();}catch(org.json.JSONException expected){}assertEquals("invalid",m.value);}
 @Test public void rejectsInvalidProvider() throws Exception {WatchHistory h=new WatchHistory(new Memory());JSONObject p=request(1);p.getJSONObject("context").put("provider","unknown");try{h.begin(p);fail();}catch(IllegalArgumentException expected){}h.record(40000,100000,false);assertEquals(0,h.list().length());}
 @Test public void retainsOnly200Entries() throws Exception {WatchHistory h=new WatchHistory(new Memory());for(int i=1;i<=205;i++){h.begin(request(i));h.record(42000,100000,false);}assertEquals(200,h.list().length());assertEquals(205,h.list().getJSONObject(0).getJSONObject("context").getInt("episode"));}
}
